import React from 'react'
import Groups3Icon from '@mui/icons-material/Groups3';

function SalientFeaturesCard({logo, heading, title}) {
    return (
        <div className='text-start p-5 rounded-xl bg-white shadow-xl w-[400px]'>
            <Groups3Icon sx={{ fontSize:'60px' }} />
            <div className='text-lg font-bold'>{heading}</div>
            <div className='ml-3'>{title}</div>
        </div>
    )
}

export default SalientFeaturesCard
